macro_rules! deps {
    () => {
        SignatureRef!();
    };
}

macro_rules! tests {
    () => {
        deps!();
        # [cfg (test)] mod tests { mod parse_signature { use gix_testtools :: to_bstr_err ; use winnow :: prelude :: * ; use crate :: { signature , SignatureRef } ; fn decode < 'i > (i : & mut & 'i [u8] ,) -> ModalResult < SignatureRef < 'i > , winnow :: error :: TreeError < & 'i [u8] , winnow :: error :: StrContext > > { signature :: decode . parse_next (i) } fn signature (name : & 'static str , email : & 'static str , time : & 'static str) -> SignatureRef < 'static > { SignatureRef { name : name . into () , email : email . into () , time , } } # [test] fn tz_minus () { let actual = decode . parse_peek (b"Sebastian Thiel <byronimo@gmail.com> 1528473343 -0230") . expect ("parse to work") . 1 ; assert_eq ! (actual , signature ("Sebastian Thiel" , "byronimo@gmail.com" , "1528473343 -0230")) ; assert_eq ! (actual . seconds () , 1528473343) ; assert_eq ! (actual . time () . expect ("valid") , gix_date :: Time { seconds : 1528473343 , offset : - 9000 , }) ; } # [test] fn tz_plus () { assert_eq ! (decode . parse_peek (b"Sebastian Thiel <byronimo@gmail.com> 1528473343 +0230") . expect ("parse to work") . 1 , signature ("Sebastian Thiel" , "byronimo@gmail.com" , "1528473343 +0230")) ; } # [test] fn email_with_space () { assert_eq ! (decode . parse_peek (b"Sebastian Thiel <\tbyronimo@gmail.com > 1528473343 +0230") . expect ("parse to work") . 1 , signature ("Sebastian Thiel" , "\tbyronimo@gmail.com " , "1528473343 +0230")) ; } # [test] fn negative_offset_0000 () { assert_eq ! (decode . parse_peek (b"Sebastian Thiel <byronimo@gmail.com> 1528473343 -0000") . expect ("parse to work") . 1 , signature ("Sebastian Thiel" , "byronimo@gmail.com" , "1528473343 -0000")) ; } # [test] fn negative_offset_double_dash () { assert_eq ! (decode . parse_peek (b"name <name@example.com> 1288373970 --700") . expect ("parse to work") . 1 , signature ("name" , "name@example.com" , "1288373970 --700")) ; } # [test] fn empty_name_and_email () { assert_eq ! (decode . parse_peek (b" <> 12345 -1215") . expect ("parse to work") . 1 , signature ("" , "" , "12345 -1215")) ; } # [test] fn invalid_signature () { assert_eq ! (decode . parse_peek (b"hello < 12345 -1215") . map_err (to_bstr_err) . expect_err ("parse fails as > is missing") . to_string () , " at 'hello < 12345 -1215'\n  0: invalid Closing '>' not found at 'hello < 12345 -1215'\n  1: expected `<name> <<email>> <timestamp> <+|-><HHMM>` at 'hello < 12345 -1215'\n") ; } # [test] fn invalid_time () { assert_eq ! (decode . parse_peek (b"hello <> abc -1215") . expect ("parse to work") . 1 , signature ("hello" , "" , "")) ; } } }
    };
}

tests!()